// Actual original HEADS context, legitimate StemsRetriever.process and CLinker
// StemBuilder; selected independent glyph parts/pixel filters, not automatic parity.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import java.awt.geom.*;
public class StemPartsFilterResearchProbe extends GridFinalProbe {
 private final Object book;public StemPartsFilterResearchProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Object en(String c,String n)throws Exception{return Class.forName("org.audiveris.omr."+c).getField(n).get(null);}
 static void set(Object o,String n,Object v)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException e){}throw new NoSuchFieldException(n);}
 static Object table(byte[] pixels,int w,int h,String orientation)throws Exception {Object bp=Class.forName("ij.process.ByteProcessor").getConstructor(int.class,int.class,byte[].class).newInstance(w,h,pixels);Object f=Class.forName("org.audiveris.omr.run.RunTableFactory").getConstructor(Class.forName("org.audiveris.omr.run.Orientation")).newInstance(en("run.Orientation",orientation));return f.getClass().getMethod("createTable",Class.forName("ij.process.ByteProcessor")).invoke(f,bp);}
 static Object glyph(int x,int y,int w,int h,String orientation)throws Exception{return Class.forName("org.audiveris.omr.glyph.Glyph").getConstructor(int.class,int.class,Class.forName("org.audiveris.omr.run.RunTable")).newInstance(x,y,table(new byte[w*h],w,h,orientation));}
 static String physical(Object g)throws Exception {Object t=call(g,"getRunTable");List<String> runs=new ArrayList<>();for(int i=0;i<(Integer)call(t,"getSize");i++){Iterator<?> it=(Iterator<?>)call(t,"iterator",i);while(it.hasNext()){Object r=it.next();runs.add("["+i+","+call(r,"getStart")+","+call(r,"getLength")+"]");}}return "{\"bounds\":"+rect(call(g,"getBounds"))+",\"orientation\":\""+call(t,"getOrientation")+"\",\"runs\":["+String.join(",",runs)+"]}";}
 static String impacts(Object p)throws Exception {if(p==null)return "null";List<String> vals=new ArrayList<>();for(int i=0;i<(Integer)call(p,"getImpactCount");i++)vals.add("{\"name\":\""+call(p,"getName",i)+"\",\"weight\":"+call(p,"getWeight",i)+",\"impact\":"+call(p,"getImpact",i)+"}");return "{\"grade\":"+call(p,"getGrade")+",\"intrinsic_ratio\":"+call(p,"getIntrinsicRatio")+",\"checks\":["+String.join(",",vals)+"]}";}
 static String stem(Object s)throws Exception {if(s==null)return "null";Line2D m=(Line2D)call(s,"getMedian");return "{\"grade\":"+call(s,"getGrade")+",\"bounds\":"+rect(call(s,"getBounds"))+",\"median\":["+m.getX1()+","+m.getY1()+","+m.getX2()+","+m.getY2()+"],\"width\":"+call(s,"getWidth")+",\"glyph\":"+physical(call(s,"getGlyph"))+",\"impacts\":"+impacts(call(s,"getImpacts"))+",\"in_sig\":"+(call(s,"getSig")!=null)+",\"id\":"+call(s,"getId")+"}";}
 public void process(){try{
  Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),sys=((List<?>)call(sheet,"getSystems")).get(0),sig=call(sys,"getSig");
  Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");
  List<Object> builders=new ArrayList<>();for(int dir:new int[]{-1,1}){Object chosen=null;for(Object head:(List<?>)get(retr,"systemHeads")){Object linker=call(head,"getLinker");if(linker==null)continue;for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object corner=call(linker,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert)),sb=get(corner,"sb");if(sb!=null&&(Integer)get(sb,"yDir")==dir){chosen=sb;break;}}if(chosen!=null)break;}if(chosen==null)throw new IllegalStateException("no initialized actual builder for direction"+dir);builders.add(chosen);}
  List<String> cases=new ArrayList<>();for(Object builder:builders){int dir=(Integer)get(builder,"yDir");Object stump=call(get(builder,"startLinker"),"getStump"),params=get(builder,"params"),skew=call(sys,"getSkew");java.awt.Rectangle base=stump==null?new java.awt.Rectangle(40,40,2,7):(java.awt.Rectangle)call(stump,"getBounds");
   for(String orientation:new String[]{"VERTICAL","HORIZONTAL"})for(int h:new int[]{3,7,15})for(int dx:new int[]{-4,-2,0,2,4})for(int dy:new int[]{-30,-10,0,10,30})for(String mode:new String[]{"empty","normal","reverse","duplicates","with-stump"}){
    Object a=glyph(base.x,base.y,2,h,orientation),b=glyph(base.x+dx,base.y+dy,2,15,orientation),c=glyph(base.x-dx,base.y-dy,2,7,orientation);List<Object> input=new ArrayList<>();if(!mode.equals("empty")){input.add(a);input.add(b);input.add(c);if(mode.equals("duplicates"))input.add(a);if(mode.equals("with-stump")&&stump!=null)input.add(stump);if(mode.equals("reverse"))Collections.reverse(input);}
    java.util.IdentityHashMap<Object,Integer> identity=new java.util.IdentityHashMap<>();if(stump!=null)identity.put(stump,0);identity.put(a,1);identity.put(b,2);identity.put(c,3);List<String> source=new ArrayList<>();for(Object g:input)source.add(""+identity.get(g));Object start=get(builder,"startLinker"),head=call(start,"getHead"),headBounds=call(call(head,"getGlyph"),"getBounds");List<Object> linkers=new ArrayList<>();linkers.add(start);for(Object priorItem:(List<?>)get(builder,"items")){if(priorItem.getClass().getSimpleName().contains("LinkerItem")){Object target=get(priorItem,"linker");if(!linkers.contains(target))linkers.add(target);}}Object filtered=call(builder,"filter",headBounds,input,linkers);List<Object> removed=new ArrayList<>();for(Object g:new Object[]{a,b,c})if(source.contains(""+identity.get(g))&&!input.contains(g))removed.add(g);List<String> itemRows=new ArrayList<>();for(Object item:(List<?>)filtered){Line2D line=(Line2D)get(item,"line");Object ig=get(item,"glyph");itemRows.add("{\"kind\":\""+item.getClass().getSimpleName()+"\",\"contrib\":"+get(item,"contrib")+",\"line\":["+line.getX1()+","+line.getY1()+","+line.getX2()+","+line.getY2()+"],\"glyph_tag\":"+(ig==null?"null":identity.get(ig))+"}");}List<String> kept=new ArrayList<>(),dropped=new ArrayList<>(),parts=new ArrayList<>();for(Object g:input)kept.add(""+identity.get(g));for(Object g:(List<?>)removed)dropped.add(""+identity.get(g));for(Object g:new Object[]{a,b,c})parts.add("{\"id\":"+identity.get(g)+",\"glyph\":"+physical(g)+"}");
    cases.add("{\"direction\":"+dir+",\"slope\":"+call(skew,"getSlope")+",\"max_alignment_dx\":"+get(params,"maxStemAlignmentDx")+",\"max_alignment_dy\":"+get(params,"maxStemAlignmentDy")+",\"mode\":\""+mode+"\",\"stump\":"+(stump==null?"null":physical(stump))+",\"parts\":["+String.join(",",parts)+"],\"input_order\":["+String.join(",",source)+"],\"retained_order\":["+String.join(",",kept)+"],\"removed_order\":["+String.join(",",dropped)+"],\"head_bounds\":"+rect(headBounds)+",\"y_range\":"+rect(get(builder,"yRange"))+",\"original_candidate_linker_count\":"+linkers.size()+",\"last_head_y\":"+get(builder,"lastHeadY")+",\"items\":["+String.join(",",itemRows)+"]}");
   }
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"scope\":\"Work-only actual CLinker StemBuilder.filter item-contribution and head-stop trial; no native implementation or automatic discovery certification\",\"cases\":["+String.join(",",cases)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
